/*
 * One row per version, newest first. Words stay in Strings: a row gets keys and the values
 * for their {tags}. Only the newest version can be reviewed (reviewSubmission refuses any
 * other), and only while it waits; an older one still pending reads as replaced.
 * A file version carries 1 to 5 files: its chip names the kind of a single file, or reads
 * Files for several, and the row draws one Version file each.
 */
if (Inputs.submissions === undefined || Inputs.kinds === undefined || Inputs.verdicts === undefined) return;
const get = (m, k) => (m && typeof m.get === 'function' ? m.get(k) : m && m[k]);
const kinds = (Inputs.kinds || []).map((k) => ({ ext: get(k, 'ext'), kind: get(k, 'kind'), labelKey: get(k, 'labelKey'), bg: get(k, 'bg'), fg: get(k, 'fg') }));
const verdicts = (Inputs.verdicts || []).map((v) => ({ value: get(v, 'value'), labelKey: get(v, 'labelKey'), bg: get(v, 'bg'), fg: get(v, 'fg') }));
let tz = String(Inputs.timezone || '');
try { new Date().toLocaleString('en-GB', { timeZone: tz || undefined }); } catch (e) { tz = ''; }
const zone = tz || Intl.DateTimeFormat().resolvedOptions().timeZone;
const when = (iso) => {
  const d = new Date(iso);
  if (!iso || isNaN(d)) return '';
  return d.toLocaleDateString('en-GB', { timeZone: zone, weekday: 'short', day: 'numeric', month: 'short' }) + ', ' +
    d.toLocaleTimeString('en-GB', { timeZone: zone, hour: '2-digit', minute: '2-digit', hourCycle: 'h23' });
};
const MUTED = { bg: 'var(--muted)', fg: 'var(--muted-foreground)' };
const filesOf = (s) => (Array.isArray(s.files) ? s.files : []).filter((f) => f && f.file);
const kindOf = (s) => {
  if (s.kind !== 'file') return kinds.find((k) => k.kind === s.kind) || {};
  const files = filesOf(s);
  if (files.length > 1) return Object.assign({ labelKey: 'work.kindFiles' }, MUTED);
  const name = String((files[0] && files[0].fileName) || '');
  const dot = name.lastIndexOf('.');
  const ext = dot > 0 ? name.slice(dot + 1).toLowerCase() : '';
  return kinds.find((k) => ext && k.ext === ext) || Object.assign({ labelKey: 'work.kindFile' }, MUTED);
};
const mode = Inputs.mode === 'coach' ? 'coach' : 'own';
const subs = (Array.isArray(Inputs.submissions) ? Inputs.submissions : []).slice().sort((a, b) => b.version - a.version);
const rows = subs.map((s, i) => {
  const k = kindOf(s);
  const review = s.review || 'pending';
  const shown = review === 'pending' && i > 0 ? 'superseded' : review;
  const v = verdicts.find((x) => x.value === shown) || {};
  return {
    id: s.id,
    mode,
    version: String(s.version),
    when: when(s.handedInAt),
    kindKey: k.labelKey || '', kindBg: k.bg || MUTED.bg, kindFg: k.fg || MUTED.fg,
    reviewKey: v.labelKey || '', reviewBg: v.bg || MUTED.bg, reviewFg: v.fg || MUTED.fg,
    isFile: s.kind === 'file', isLink: s.kind === 'link', isText: s.kind === 'text',
    files: filesOf(s).map((f, j) => ({ id: s.id + '-file-' + j, file: f.file, fileName: f.fileName || '', mode })),
    url: s.url || '', text: s.text || '',
    note: s.note || '', hasNote: !!s.note,
    reviewNote: s.reviewNote || '', hasReviewNote: !!s.reviewNote, reviewedWhen: when(s.reviewedAt),
    canReview: Inputs.canReview === true && i === 0 && review === 'pending'
  };
});
Outputs.rows = rows;
Outputs.count = rows.length;
Outputs.hasRows = rows.length > 0;
